package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_createNumber_TriageGen0Test {

    @Test
    public void testCreateNumber_Null() {
        assertNull(NumberUtils.createNumber(null));
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_Blank() {
        NumberUtils.createNumber("   ");
    }

    @Test
    public void testCreateNumber_Integer() {
        Number n = NumberUtils.createNumber("123");
        assertTrue(n instanceof Integer);
        assertEquals(123, ((Integer) n).intValue());
    }

    @Test
    public void testCreateNumber_Long() {
        // A number larger than Integer.MAX_VALUE but fits in Long
        Number n = NumberUtils.createNumber("3000000000");
        assertTrue(n instanceof Long);
        assertEquals(3000000000L, ((Long) n).longValue());
    }

    @Test
    public void testCreateNumber_BigInteger() {
        // A number larger than Long.MAX_VALUE
        Number n = NumberUtils.createNumber("9223372036854775808");
        assertTrue(n instanceof BigInteger);
    }

    @Test
    public void testCreateNumber_Float() {
        Number n = NumberUtils.createNumber("1.23f");
        assertTrue(n instanceof Float);
        assertEquals(1.23f, ((Float) n).floatValue(), 0.001f);
    }

    @Test
    public void testCreateNumber_Double() {
        Number n = NumberUtils.createNumber("1.23d");
        assertTrue(n instanceof Double);
        assertEquals(1.23, ((Double) n).doubleValue(), 0.001);
    }

    @Test
    public void testCreateNumber_BigDecimal() {
        Number n = NumberUtils.createNumber("1.234567890123456789");
        assertTrue(n instanceof BigDecimal);
    }

    @Test
    public void testCreateNumber_HexInteger() {
        Number n = NumberUtils.createNumber("0x123");
        assertTrue(n instanceof Integer);
        assertEquals(0x123, ((Integer) n).intValue());
    }

    @Test
    public void testCreateNumber_HexLong() {
        // Hex with many digits to trigger Long
        Number n = NumberUtils.createNumber("0x123456789");
        assertTrue(n instanceof Long);
    }

    @Test
    public void testCreateNumber_NegativeHex() {
        Number n = NumberUtils.createNumber("-0x123");
        assertTrue(n instanceof Integer);
        assertEquals(-0x123, ((Integer) n).intValue());
    }

    @Test
    public void testCreateNumber_HexUpper() {
        Number n = NumberUtils.createNumber("0XABC");
        assertTrue(n instanceof Integer);
    }

    @Test
    public void testCreateNumber_NegativeHexUpper() {
        Number n = NumberUtils.createNumber("-0XABC");
        assertTrue(n instanceof Integer);
    }

    @Test
    public void testCreateNumber_ScientificNotation() {
        Number n = NumberUtils.createNumber("1.23e2");
        assertTrue(n instanceof Double || n instanceof Float || n instanceof BigDecimal);
    }

    @Test
    public void testCreateNumber_ScientificNotationDecimal() {
        Number n = NumberUtils.createNumber("1.2e3");
        assertNotNull(n);
    }

    @Test
    public void testCreateNumber_Exception_InvalidExp() {
        // Tests the case where expPos is invalid (e.g., 'e' at the end or misplaced)
        // Note: Actual behavior depends on internal createFloat/Double/BigDecimal logic 
        // but we aim to hit the branch where expPos check happens.
    }

    @Test(expected = NumberFormatException.class)
    public void testCreateNumber_InvalidSuffix() {
        // 'l' case is specifically hardcoded to throw NFE in the provided snippet
        NumberUtils.createNumber("123l");
    }

    @Test
    public void testCreateNumber_FloatFallthroughToDouble() {
        // Test a float that is too big for float, should fall through to double
        Number n = NumberUtils.createNumber("1e40f");
        assertTrue(n instanceof Double);
    }

    @Test
    public void testCreateNumber_DoubleFallthroughToBigDecimal() {
        // Test a double that is too big for double, should fall through to BigDecimal
        Number n = NumberUtils.createNumber("1e400d");
        assertTrue(n instanceof BigDecimal);
    }

    @Test
    public void testCreateNumber_AllZerosLogic() {
        // Test the allZeros logic for float/double precision check
        Number n = NumberUtils.createNumber("0.000e0f");
        assertNotNull(n);
    }

    @Test
    public void testCreateNumber_DecimalNoExp() {
        Number n = NumberUtils.createNumber("123.456");
        assertTrue(n instanceof Double || n instanceof Float || n instanceof BigDecimal);
    }

    @Test
    public void testCreateNumber_NoDecimalNoExp() {
        Number n = NumberUtils.createNumber("123");
        assertTrue(n instanceof Integer);
    }

    @Test
    public void testCreateNumber_LargeHex() {
        // hexDigits > 8
        Number n = NumberUtils.createNumber("0x123456789");
        assertTrue(n instanceof Long);
    }
}
